package com.nivor.notification;
import com.nivor.goal.*;import com.nivor.planner.*;import com.nivor.project.*;import com.nivor.task.*;import java.time.LocalDate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class DeadlineNotificationJob{private final TaskRepository tasks;private final CalendarEventRepository events;private final GoalRepository goals;private final ProjectRepository projects;private final NotificationService notifications;public DeadlineNotificationJob(TaskRepository t,CalendarEventRepository e,GoalRepository g,ProjectRepository p,NotificationService n){tasks=t;events=e;goals=g;projects=p;notifications=n;}
 @Scheduled(cron="0 0 9 * * *") @Transactional public void generateTomorrowReminders(){LocalDate tomorrow=LocalDate.now().plusDays(1);tasks.findAll().stream().filter(t->t.getDueDate()!=null&&t.getDueDate().equals(tomorrow)&&t.getStatus()!=TaskStatus.COMPLETED).forEach(t->notifications.create(t.getUser(),NotificationType.TASK_DUE,"Task due tomorrow",t.getTitle(),"TASK",t.getId()));events.findAll().stream().filter(e->e.getStartTime().toLocalDate().equals(tomorrow)).forEach(e->notifications.create(e.getUser(),NotificationType.EVENT_REMINDER,"Event tomorrow",e.getTitle(),"EVENT",e.getId()));goals.findAll().stream().filter(g->g.getDeadline()!=null&&g.getDeadline().equals(tomorrow)&&g.getStatus()==GoalStatus.ACTIVE).forEach(g->notifications.create(g.getUser(),NotificationType.GOAL_DEADLINE,"Goal deadline tomorrow",g.getTitle(),"GOAL",g.getId()));projects.findAll().stream().filter(p->p.getDeadline()!=null&&p.getDeadline().equals(tomorrow)&&p.getStatus()!=ProjectStatus.COMPLETED).forEach(p->notifications.create(p.getUser(),NotificationType.PROJECT_DEADLINE,"Project deadline tomorrow",p.getName(),"PROJECT",p.getId()));}
}
